public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnaltyeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
            if (snapshot != null) {
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timeRange.getId() == snapshot.getProfileId() && snapshot.getTimestamp() >= timeRange.getStartTime() && snapshot.getTimestamp() <= timeRange.getEndTime()) {
                        threadSnapshots.add(snapshot);
                        break;
                    }
                }
            }
        }
    }

    return threadSnapshots;
}
```
